sys_script_include.script:
function GetParam(strParam,callbackCheckParameter,ajaxProcessorObject)
{
	strParam = GetStringValue(strParam);
	if (strParam == '')
	{
		return '';
	}
	var strInsecureValue = '';
	if (IsObject(ajaxProcessorObject) == true)
	{
		if (IsFunction(ajaxProcessorObject.getParameter) == true)
		{
			strInsecureValue = GetStringValue(ajaxProcessorObject.getParameter(
				strParam));
			if (strInsecureValue == '')
			{
				strInsecureValue = GetStringValue(ajaxProcessorObject.getParameter(
					'sysparm_'+strParam));
			}
			if (strInsecureValue == '')
			{
				strInsecureValue = GetStringValue(ajaxProcessorObject.getParameter(
					'sysparm_ajax_processor_'+strParam));
			}
		}
	}
	if (strInsecureValue == '')
	{
		if (typeof RP != 'undefined')
		{
			strInsecureValue = GetStringValue(RP.getParameterValue(strParam));
		}
	}
	if (strInsecureValue == '')
	{
		if (typeof gs.action.getGlideURI != 'undefined')
		{
			// This covers scripted REST API endpoints and client-callable Script Includes
			var glideUri = RunScriptInGlobalScope('result = gs.action.getGlideURI();');
			if (glideUri != null)
			{
				strInsecureValue = GetStringValue(glideUri.get(strParam));
				if (strInsecureValue == '')
				{
					strInsecureValue = GetStringValue(glideUri.get('sysparm_'+strParam));
				}
				if (strInsecureValue == '')
				{
					strInsecureValue = GetStringValue(glideUri.get('sysparm_ajax_processor_'+strParam));
				}
			}
		}
	}
	if (strInsecureValue == '')
	{
		return '';
	}
	var strValue = '';
	if (IsFunction(callbackCheckParameter) == false)
	{
		callbackCheckParameter = IsSecureParameterValue;
	}
	if (callbackCheckParameter(strInsecureValue) == true)
	{
		strValue = strInsecureValue;
	}
	return strValue;
}
